            aOrbiterB = ((aWandererH + RotL64(aPrevious, 39U)) + RotL64(aCarry, 11U)) + 0xBCC3173F829DF4BCULL;
            aOrbiterD = (aWandererE + RotL64(aCross, 43U)) + 0x734589E995EBEF36ULL;
