            aWandererC = aWandererC + (((RotL64(aScatter, 13U) + aOrbiterK) + RotL64(aOrbiterC, 11U)) + RotL64(aCarry, 43U));
            aWandererB = aWandererB ^ (((RotL64(aPrevious, 27U) + RotL64(aOrbiterG, 3U)) + aOrbiterF) + aTwistWandererUpdateSaltF[(((255U - aIndex) + 217U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aCross, 23U) + RotL64(aOrbiterF, 36U)) + aOrbiterK);
