            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xFBB58C4554A7E181ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x4B8AF40693C35F9BULL;
