            //
            aOrbiterC = ((aOrbiterC + aOrbiterK) + 0xFBBC3EE8CCBA4279ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 1U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xDDDAC9FBD52F4423ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x7F79CF1ABA3BD79FULL), 39U);
